def parse_value(text):
    """Convert an environment string: "true"/"yes"/"on"/"1" (any case, surrounding spaces ignored) -> True,
    "false"/"no"/"off"/"0" -> False, a decimal integer like "42" or "-7" -> int, a decimal number like "2.5" -> float,
    "" or "null"/"none" (any case) -> None, anything else -> the stripped string unchanged. Note "1" and "0" are booleans."""
    stripped_text = text.strip()
    lower_text = stripped_text.lower()

    # Booleans
    if lower_text in ("true", "yes", "on", "1"):
        return True
    if lower_text in ("false", "no", "off", "0"):
        return False

    # None
    if stripped_text == "" or lower_text in ("null", "none"):
        return None

    # Numbers
    try:
        return int(stripped_text)
    except ValueError:
        pass # Not an int, try float

    try:
        return float(stripped_text)
    except ValueError:
        pass # Not a float

    # Default to stripped string
    return stripped_text
